import type {
  AssetRef,
  CameraBookmark,
  ConstraintSpec,
  DerivedState,
  EditableObjectClass,
  FixedElement,
  HandoffGrantRecord,
  HandoffRedeemRequest,
  HandoffRedeemResponse,
  JobRecord,
  MaterialState,
  NamedWallRef,
  ObjectClass,
  Opening,
  Point2D,
  Point3D,
  Polygon2D,
  Pose3D,
  ReasonCode,
  RectOnSurface,
  Room,
  RoomPlanCaptureRequest,
  RoomPlanCaptureResponse,
  RoomPlanFixedElementSeed,
  RoomPlanObjectSeed,
  RoomPlanOpeningSeed,
  RoomPlanPayload,
  RoomPlanSurfaceSeed,
  Scene,
  SceneObject,
  SupportRelation,
  Surface,
  SurfaceFrame,
  SplatAssetRecord,
  SupplementaryDetection,
  VideoUploadTokenRecord,
  VideoUploadRequest,
  VideoUploadResponse,
} from "@roomview/contracts";

const EDITABLE_OBJECT_CLASSES = new Set<EditableObjectClass>([
  "bed",
  "nightstand",
  "desk",
  "chair",
  "table",
  "dresser",
  "bookshelf",
  "sofa",
  "rug",
  "lamp",
  "television",
  "storage",
]);

const WALL_NAME_TO_AZIMUTH: Record<string, number> = {
  "north wall": 0,
  "east wall": 90,
  "south wall": 180,
